/* ============================================
   RedRoom Fitness — Design System
   Dark Mode (OLED) / Bold / Intense / Premium
   ============================================ */

/* ---------- Fonts ---------- */
@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800;900&family=Barlow:wght@300;400;500;600;700&display=swap');

/* ---------- CSS Variables ---------- */
:root {
  /* Backgrounds */
  --bg-deep:     #0a0a0a;
  --bg-primary:  #111111;
  --bg-surface:  #1a1a1a;
  --bg-elevated: #222222;
  --bg-muted:    #2a2a2a;

  /* Accent — RedRoom Red */
  --accent:        #E63946;
  --accent-hover:  #ff4d5a;
  --accent-glow:   rgba(230, 57, 70, 0.35);
  --accent-soft:   rgba(230, 57, 70, 0.15);
  --accent-border: rgba(230, 57, 70, 0.4);

  /* Text */
  --text-primary:   #FFFFFF;
  --text-secondary: #B0B0B0;
  --text-muted:     #707070;
  --text-inverse:   #0a0a0a;

  /* Borders */
  --border-default: #2a2a2a;
  --border-light:   #3a3a3a;

  /* Typography */
  --font-heading: 'Barlow Condensed', sans-serif;
  --font-body:    'Barlow', sans-serif;

  /* Spacing scale (8px base) */
  --space-1:  4px;
  --space-2:  8px;
  --space-3:  12px;
  --space-4:  16px;
  --space-5:  20px;
  --space-6:  24px;
  --space-8:  32px;
  --space-10: 40px;
  --space-12: 48px;
  --space-16: 64px;
  --space-20: 80px;
  --space-24: 96px;

  /* Radii */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;

  /* Transitions */
  --ease-out:  cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in:   cubic-bezier(0.4, 0, 1, 1);
  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
  --duration-fast: 150ms;
  --duration-base: 250ms;
  --duration-slow: 350ms;

  /* Layout */
  --max-width: 1200px;
  --nav-height: 72px;
}

/* ---------- Reset & Base ---------- */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-primary);
  background: var(--bg-deep);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

img {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
  color: inherit;
}

ul, ol {
  list-style: none;
}

input {
  font-family: inherit;
  font-size: inherit;
}

/* ---------- Typography ---------- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.1;
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

h1 { font-size: clamp(2.5rem, 6vw, 5rem); }
h2 { font-size: clamp(2rem, 4vw, 3.5rem); }
h3 { font-size: clamp(1.25rem, 2.5vw, 2rem); }
h4 { font-size: clamp(1rem, 1.5vw, 1.25rem); }

.page-title {
  font-size: clamp(2.5rem, 6vw, 4.5rem);
  font-weight: 900;
  text-align: center;
  margin-bottom: var(--space-4);
}

.section-title {
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  margin-bottom: var(--space-4);
}

.section-subtitle {
  font-family: var(--font-body);
  font-size: 1.125rem;
  color: var(--text-secondary);
  line-height: 1.7;
  max-width: 640px;
}

.gradient-text {
  background: linear-gradient(135deg, var(--accent) 0%, #ff6b6b 50%, var(--accent-hover) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* ---------- Layout ---------- */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-6);
}

.section {
  padding: var(--space-24) 0;
}

.section-dark {
  background: var(--bg-primary);
}

.section-accent {
  background: var(--accent);
  color: var(--text-primary);
}

.text-center { text-align: center; }

.grid-2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-8);
}

.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-6);
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 0.95rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: var(--space-4) var(--space-8);
  border-radius: var(--radius-sm);
  transition: all var(--duration-fast) var(--ease-out);
  cursor: pointer;
  white-space: nowrap;
  min-height: 48px;
  min-width: 48px;
}

.btn-primary {
  background: var(--accent);
  color: #fff;
}
.btn-primary:hover {
  background: var(--accent-hover);
  box-shadow: 0 0 30px var(--accent-glow);
  transform: translateY(-1px);
}
.btn-primary:active {
  transform: translateY(0);
  transition: transform 50ms var(--ease-out);
}

.btn-outline {
  background: transparent;
  color: #fff;
  border: 2px solid var(--border-light);
}
.btn-outline:hover {
  border-color: var(--accent);
  color: var(--accent);
  box-shadow: 0 0 20px var(--accent-soft);
}

.btn-ghost {
  background: transparent;
  color: var(--text-secondary);
}
.btn-ghost:hover {
  color: #fff;
  background: rgba(255,255,255,0.05);
}

.btn-lg {
  padding: var(--space-5) var(--space-10);
  font-size: 1.1rem;
}

.btn-sm {
  padding: var(--space-2) var(--space-5);
  font-size: 0.8rem;
}

/* ---------- Top Announcement Bar ---------- */
.announcement-bar {
  background: var(--accent);
  color: #fff;
  text-align: center;
  padding: var(--space-2) var(--space-4);
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  position: relative;
  z-index: 1001;
}
.announcement-bar a {
  font-weight: 700;
  text-decoration: underline;
  text-underline-offset: 3px;
  margin-left: var(--space-2);
}
.announcement-bar a:hover {
  color: rgba(255,255,255,0.8);
}

/* ---------- Navigation ---------- */
.nav {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(10, 10, 10, 0.92);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-bottom: 1px solid var(--border-default);
  height: var(--nav-height);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-6);
}

.nav-logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 900;
  color: #fff;
  letter-spacing: 0.04em;
  display: flex;
  align-items: center;
  gap: var(--space-2);
}
.nav-logo span {
  color: var(--accent);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: var(--space-1);
}

.nav-links a {
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-secondary);
  padding: var(--space-2) var(--space-3);
  border-radius: var(--radius-sm);
  transition: color var(--duration-fast) var(--ease-out);
}
.nav-links a:hover,
.nav-links a.active {
  color: #fff;
}
.nav-links a.active {
  color: var(--accent);
}

.nav-cta {
  display: flex;
  align-items: center;
  gap: var(--space-3);
}

.nav-menu-btn {
  display: none;
  width: 44px;
  height: 44px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 0;
  background: none;
  border: none;
  cursor: pointer;
}
.nav-menu-btn span {
  display: block;
  width: 22px;
  height: 2px;
  background: #fff;
  border-radius: 2px;
  transition: all var(--duration-fast) var(--ease-out);
}
.nav-menu-btn.active span:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}
.nav-menu-btn.active span:nth-child(2) {
  opacity: 0;
}
.nav-menu-btn.active span:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

/* ---------- Footer ---------- */
.footer {
  background: var(--bg-primary);
  border-top: 1px solid var(--border-default);
  padding: var(--space-20) 0 var(--space-10);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: var(--space-12);
  margin-bottom: var(--space-16);
}

.footer-brand {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 900;
  letter-spacing: 0.04em;
  margin-bottom: var(--space-3);
}
.footer-brand span { color: var(--accent); }

.footer-tagline {
  color: var(--text-muted);
  font-size: 0.9rem;
  line-height: 1.6;
  max-width: 280px;
}

.footer-heading {
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-secondary);
  margin-bottom: var(--space-5);
}

.footer-links {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.footer-links a {
  font-size: 0.9rem;
  color: var(--text-muted);
  transition: color var(--duration-fast) var(--ease-out);
}
.footer-links a:hover {
  color: var(--accent-hover);
}

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: var(--space-8);
  border-top: 1px solid var(--border-default);
  font-size: 0.8rem;
  color: var(--text-muted);
}

.country-select {
  background: var(--bg-surface);
  color: var(--text-primary);
  border: 1px solid var(--border-default);
  padding: var(--space-2) var(--space-4);
  border-radius: var(--radius-sm);
  font-family: var(--font-body);
  font-size: 0.85rem;
  cursor: pointer;
  min-height: 44px;
}
.country-select:focus {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

/* ---------- Hero Section ---------- */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
  background: var(--bg-deep);
}

.hero-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
}

.hero-gradient {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 60% 40%, var(--accent-soft) 0%, transparent 60%),
    radial-gradient(ellipse at 20% 80%, rgba(230,57,70,0.08) 0%, transparent 50%),
    radial-gradient(ellipse at center, transparent 0%, var(--bg-deep) 100%);
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 860px;
  padding: var(--space-24) var(--space-6);
}

.hero-badge {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--accent);
  border: 1px solid var(--accent-border);
  padding: var(--space-1) var(--space-4);
  border-radius: 999px;
  margin-bottom: var(--space-6);
}

.hero-title {
  font-size: clamp(3rem, 8vw, 6rem);
  font-weight: 900;
  line-height: 0.95;
  margin-bottom: var(--space-6);
  letter-spacing: -0.01em;
}

.hero-subtitle {
  font-family: var(--font-body);
  font-size: clamp(1rem, 2vw, 1.25rem);
  color: var(--text-secondary);
  line-height: 1.7;
  max-width: 600px;
  margin: 0 auto var(--space-10);
}

.hero-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-4);
  flex-wrap: wrap;
}

/* Hero accent line */
.hero-accent-line {
  width: 60px;
  height: 3px;
  background: var(--accent);
  margin: 0 auto var(--space-6);
}

/* ---------- Cards ---------- */
.card {
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  transition: all var(--duration-base) var(--ease-out);
  position: relative;
  overflow: hidden;
}
.card:hover {
  border-color: var(--accent-border);
  box-shadow: 0 8px 40px rgba(0,0,0,0.4);
  transform: translateY(-2px);
}

.card-accent {
  border-top: 3px solid var(--accent);
}

.card-icon {
  width: 56px;
  height: 56px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--accent-soft);
  border-radius: var(--radius-md);
  margin-bottom: var(--space-5);
  font-size: 1.5rem;
}

.card-title {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  margin-bottom: var(--space-3);
}

.card-text {
  color: var(--text-secondary);
  font-size: 0.95rem;
  line-height: 1.7;
}

/* ---------- Community Promo ---------- */
.community-promo {
  padding: var(--space-24) 0;
  background: var(--bg-primary);
  position: relative;
  overflow: hidden;
}
.community-promo::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 30% 50%, rgba(230,57,70,0.06) 0%, transparent 70%);
}

/* ---------- Two Ways Section ---------- */
.two-ways-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-8);
}

.way-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-xl);
  padding: var(--space-12) var(--space-10);
  position: relative;
  overflow: hidden;
  transition: all var(--duration-base) var(--ease-out);
}
.way-card:hover {
  border-color: var(--accent-border);
  box-shadow: 0 0 60px var(--accent-soft);
}

.way-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: var(--accent);
}

.way-label {
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--accent);
  margin-bottom: var(--space-4);
}

.way-title {
  font-size: 2rem;
  margin-bottom: var(--space-4);
}

.way-text {
  color: var(--text-secondary);
  line-height: 1.7;
  margin-bottom: var(--space-8);
}

/* ---------- Studio Experience ---------- */
.studio-section {
  position: relative;
  padding: var(--space-24) 0;
  background: var(--bg-deep);
  overflow: hidden;
}

.studio-section::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 200px;
  background: linear-gradient(to top, var(--accent-soft), transparent);
  pointer-events: none;
}

.studio-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-16);
  align-items: center;
}

.studio-visual {
  position: relative;
  aspect-ratio: 4/5;
  background: var(--bg-surface);
  border-radius: var(--radius-xl);
  overflow: hidden;
  border: 1px solid var(--border-default);
}

.studio-visual-inner {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background:
    radial-gradient(ellipse at center, rgba(230,57,70,0.2) 0%, transparent 70%),
    linear-gradient(135deg, var(--bg-surface) 0%, #1a1012 100%);
}

.studio-visual-icon {
  font-size: 5rem;
  opacity: 0.15;
}

/* ---------- CTA Sections ---------- */
.cta-section {
  background: var(--accent);
  padding: var(--space-20) 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.cta-section::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, rgba(255,255,255,0.1) 0%, transparent 70%);
  pointer-events: none;
}

.cta-title {
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 900;
  color: #fff;
  margin-bottom: var(--space-8);
}

.cta-dark {
  background: var(--bg-primary);
}
.cta-dark .cta-title {
  color: #fff;
}

/* ---------- Carousel ---------- */
.carousel-section {
  padding: var(--space-20) 0;
  background: var(--bg-primary);
}

.carousel {
  position: relative;
  overflow: hidden;
  border-radius: var(--radius-xl);
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
}

.carousel-track {
  display: flex;
  transition: transform 0.5s var(--ease-out);
  will-change: transform;
}

.carousel-slide {
  min-width: 100%;
  aspect-ratio: 16/9;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.carousel-slide-inner {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 2rem;
  font-weight: 800;
  color: rgba(255,255,255,0.1);
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.slide-1 { background: linear-gradient(135deg, #1a1012 0%, #1a0a0c 100%); }
.slide-2 { background: linear-gradient(135deg, #10111a 0%, #0a0c1a 100%); }
.slide-3 { background: linear-gradient(135deg, #1a101a 0%, #0c0a1a 100%); }
.slide-4 { background: linear-gradient(135deg, #101a10 0%, #0a1a0c 100%); }

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: rgba(0,0,0,0.6);
  backdrop-filter: blur(10px);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
  cursor: pointer;
  border: 1px solid rgba(255,255,255,0.1);
  transition: all var(--duration-fast) var(--ease-out);
  z-index: 2;
}
.carousel-btn:hover {
  background: var(--accent);
  border-color: var(--accent);
}
.carousel-btn.prev { left: var(--space-4); }
.carousel-btn.next { right: var(--space-4); }

.carousel-dots {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-5) 0;
  position: absolute;
  bottom: var(--space-4);
  left: 50%;
  transform: translateX(-50%);
  z-index: 2;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: rgba(255,255,255,0.3);
  border: none;
  cursor: pointer;
  transition: all var(--duration-fast) var(--ease-out);
  padding: 0;
}
.carousel-dot.active {
  background: var(--accent);
  box-shadow: 0 0 10px var(--accent-glow);
}

/* ---------- Weekly Schedule Table ---------- */
.schedule-table {
  width: 100%;
  border-collapse: collapse;
  background: var(--bg-surface);
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--border-default);
}

.schedule-table thead {
  background: var(--accent);
}

.schedule-table th {
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: #fff;
  padding: var(--space-4) var(--space-6);
  text-align: left;
}

.schedule-table td {
  padding: var(--space-5) var(--space-6);
  border-top: 1px solid var(--border-default);
  font-size: 0.95rem;
}

.schedule-table tbody tr {
  transition: background var(--duration-fast) var(--ease-out);
}
.schedule-table tbody tr:hover {
  background: var(--bg-elevated);
}

.schedule-table .day-col {
  font-family: var(--font-heading);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: #fff;
  white-space: nowrap;
}

.schedule-table .focus-col {
  color: var(--text-secondary);
}

.schedule-table .cta-col {
  text-align: right;
}

/* ---------- Floor / Treadmill Toggle ---------- */
.toggle-section {
  padding: var(--space-20) 0;
