      dot.addEventListener('click', (function(idx) { return function() { goTo(idx); }; })(i));
      dotsContainer.appendChild(dot);
    }
  }

  function update() {
    track.style.transform = 'translateX(-' + (current * 100) + '%)';
    var dots = dotsContainer.children;
    for (var i = 0; i < dots.length; i++) {
      dots[i].classList.toggle('active', i === current);
    }
  }

  function goTo(index) {
    current = ((index % total) + total) % total;
    update();
  }

  function next() { goTo(current + 1); }
  function prev() { goTo(current - 1); }

  document.getElementById('carouselNext').addEventListener('click', next);
  document.getElementById('carouselPrev').addEventListener('click', prev);

  // Touch swipe
  track.addEventListener('touchstart', function(e) {
    startX = e.touches[0].clientX;
    dragging = true;
  }, { passive: true });
  track.addEventListener('touchmove', function(e) {
    if (!dragging) return;
    diffX = e.touches[0].clientX - startX;
  }, { passive: true });
  track.addEventListener('touchend', function() {
    if (!dragging) return;
    if (diffX > 50) prev();
    else if (diffX < -50) next();
    dragging = false; diffX = 0;
  });

  // Mouse drag — attach on mousedown, clean up on mouseup
  track.addEventListener('mousedown', function(e) {
    startX = e.clientX;
    dragging = true;
    track.style.cursor = 'grabbing';
    e.preventDefault();

    function onMove(ev) {
      if (!dragging) return;
      diffX = ev.clientX - startX;
    }
    function onUp() {
      if (!dragging) return;
      if (diffX > 50) prev();
      else if (diffX < -50) next();
      dragging = false; diffX = 0;
      track.style.cursor = '';
      window.removeEventListener('mousemove', onMove);
      window.removeEventListener('mouseup', onUp);
    }

    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
  });

  // Keyboard nav
  document.getElementById('carousel').addEventListener('keydown', function(e) {
    if (e.key === 'ArrowLeft') { prev(); e.preventDefault(); }
    if (e.key === 'ArrowRight') { next(); e.preventDefault(); }
  });

  createDots();
  update();
})();
</script>

